    # Extend the central-color tile as a 2-cell-thick rectangular border outside the frame.
    colors = {}
    for row in grid:
        for v in row:
            if v:
                colors[v] = colors.get(v, 0) + 1
    frame = max(colors, key=colors.get)
    center = next(v for v in colors if v != frame)
    pts = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    out=[row[:] for row in grid]
    for r in range(max(0,r0-2), min(len(grid),r1+3)):
        for c in range(max(0,c0-2), min(len(grid[0]),c1+3)):
            if grid[r][c] == 0:
                out[r][c]=center
    return out
